import * as E from './engine.js?v=122';
import * as S from './states.js?v=122';
import * as D from './deployables.js?v=122';
import * as P from './pregame.js?v=122';
import {inZone} from './hacking.js?v=122';
export const SOURCES=['https://infinitythewiki.com/Minelayer','https://infinitythewiki.com/Decoy_State'];
function current(s,u){if(s.phase!=='deploy'||u.deploymentPending||u.isDeployable||u.isDecoy)return false;if(!s.pregame)return !u.deploymentLocked;return s.pregame.stage==='deploy'&&P.deploymentTeam(s)===u.team&&(P.reserveStep(s)===s.pregame.reserves[u.team].includes(u.id));}
export function actions(s,u){if(!current(s,u))return [];const out=[],items=D.available(u,{deployableOnly:true});if(u.minelayer&&(u.minelayerUsed||0)<Number(u.minelayer)&&items.length)out.push({id:'minelayer',name:'布雷者部署',items});if(u.decoy&&!u.decoyPlaced)out.push({id:'decoy',name:'部署诱饵',count:Math.min(2,Number(u.decoy))});return out;}
function legal(s,owner,entity,p,terrain){if(p.wall)return '不能部署在垂直墙面';if(!P.inDeployment({...owner,s:entity.s,baseRadius:entity.baseRadius},p,{attemptInfiltration:!!owner.infiltrationAttempt}))return '部署物或诱饵必须在使用者获准部署的区域内';const units=s.units.filter(v=>!v.deploymentPending&&!v.offTable&&S.onTable(v));const bad=E.validPosition(entity,p,units,terrain);if(bad)return bad;if(units.some(v=>v.team!==owner.team&&E.edgeDistance({...entity,...p},v)<.025))return '不能部署接触敌人或中立模型';if((s.objectives||[]).some(o=>Math.abs((o.z||0)-(p.z||0))<.1&&Math.hypot(p.x-o.x,p.y-o.y)<=E.radius(entity)+(o.r||0)+.025))return '不能部署接触任务目标';return '';}
export function placeMine(s,u,itemId,p,{terrain=s.terrain||[],templates={}}={}){const action=actions(s,u).find(a=>a.id==='minelayer');if(!action||!action.items.includes(itemId))return {error:'当前不能使用该布雷者部署选项'};const id=`pregame-${u.minelayerUsed||0}`,entity=D.entity(u,itemId,p,id);entity.deploymentSide=u.deploymentSide;entity.deploymentLocked=true;entity.deploymentPending=false;entity.minelayerOwnerId=u.id;const bad=legal(s,u,entity,p,terrain);if(bad)return {error:bad};u.deploymentLocked=true;if(!inZone(u,entity))return {error:'部署物超出布雷者控制区（8″）；测量后模型位置已固定'};if((D.isMine(itemId)||D.ITEMS[itemId]?.perimeter)&&s.units.some(v=>v.team!==u.team&&v.team!==-1&&!v.deploymentPending&&S.onTable(v)&&!v.isDeployable&&(D.ITEMS[itemId]?.perimeter?inZone(entity,v):D.inTriggerArea(entity,v,terrain,templates))))return {error:D.ITEMS[itemId]?.perimeter?'布雷者部署时，外围装备控制区内不能有敌方模型或迷彩标记':'布雷者部署时，地雷触发区内不能有敌方模型或迷彩标记'};const consumed=D.consume(u,itemId,{token:`minelayer-${u.id}-${u.minelayerUsed||0}`});if(consumed.error)return {error:consumed.error};Object.assign(u,consumed.unit);u.minelayerUsed=(u.minelayerUsed||0)+1;s.units.push(entity);return {error:'',entity};}
export function placeDecoys(s,u,points,{terrain=s.terrain||[]}={}){const action=actions(s,u).find(a=>a.id==='decoy');if(!action||!Array.isArray(points)||!points.length||points.length>action.count)return {error:'当前诱饵数量或部署选项无效'};const entities=points.map((p,i)=>({...u,...p,id:`decoy-${u.id}-${i+1}`,name:`${u.name||u.id} · 诱饵 ${i+1}`,isDecoy:true,decoyOwnerId:u.id,noOrders:true,noARO:true,lieutenant:false,regularOrderCount:0,irregularTroop:false,tacticalAwareness:false,points:0,loadout:[],deployableItems:[],armyWeapons:{},repeater:false,hackingDevice:null,decoy:0,minelayer:0,ftLevel:0,deploymentLocked:true,deploymentPending:false,states:[...(u.states||[]).filter(x=>x!=='hiddenDeployment'),'decoyReplica']}));for(let i=0;i<entities.length;i++){const bad=legal({...s,units:[...s.units,...entities.slice(0,i)]},u,entities[i],points[i],terrain);if(bad)return {error:bad};}u.deploymentLocked=true;if(entities.some(v=>!inZone(u,v)))return {error:'诱饵必须在真实模型控制区内保持一致性；测量后模型位置已固定'};u.decoyPlaced=true;u.ftLevel=0;u.states=[...new Set([...(u.states||[]),'decoy'])];s.units.push(...entities);return {error:'',entities};}
export function cancelDecoys(s,u,event,details={}){if(!u)return [];if(u.isDecoy){if(!['discovered','hit','contact'].includes(event))return [];u.hp=-1;u.states=['dead'];return [u.id];}if(!(u.states||[]).includes('decoy'))return [];const reveal=['discovered','contact','save','failedDeployment','impetuous','retreat'].includes(event)||event==='declaration'&&(details.attack||details.requiresRoll&&details.skill!=='combatJump'||details.skill==='lookOut'||details.longSkill&&!['cautious','cautiousMove','parachutist','combatJump'].includes(details.skill));if(!reveal)return [];const removed=[];for(const v of s.units)if(v.isDecoy&&v.decoyOwnerId===u.id&&!S.has(v,'dead')){v.hp=-1;v.states=['dead'];removed.push(v.id);}u.states=(u.states||[]).filter(x=>x!=='decoy');return removed;}
export function failedSuperiorDeployment(s,u){const removed=cancelDecoys(s,u,'failedDeployment');for(const v of s.units)if(v.minelayerOwnerId===u.id&&!S.has(v,'dead')){v.hp=-1;v.states=['dead'];removed.push(v.id);}return removed;}
// Deployment entities retain their owner's permission, not the ordinary 12-inch
// zone. They do not independently make an Infiltration roll.
export function deploymentProfile(s,u){const owner=s.units.find(n=>n.id===(u.minelayerOwnerId||u.decoyOwnerId));if(!owner)return u;const keys=['deploymentSide','deploymentDepth','enemyDeploymentDepth','deploymentExclusions','forwardDeployment','infiltration','infiltrationAttempt','infiltrationFailed','impersonation'];return {...u,...Object.fromEntries(keys.map(k=>[k,owner[k]]))};}
